/** Size class of a Turn by its estimated tokens, smallest first. */
export type Bucket = "tiny" | "small" | "medium" | "large" | "huge";

/** Exclusive upper bound of each bounded Bucket; `huge` has none. */
const BELOW: ReadonlyArray<readonly [Bucket, number]> = [
	["tiny", 350],
	["small", 1800],
	["medium", 7000],
	["large", 24000],
];

/** Lower bounds inclusive, upper bounds exclusive: 350 is `small`, 24000 is `huge`. */
export function bucketOf(tokens: number): Bucket {
	for (const [bucket, below] of BELOW) if (tokens < below) return bucket;
	return "huge";
}

