// suite: TT-5082
import { describe, expect, test } from "bun:test";

import { bucketOf, weighted } from "./budget-table.ts";

describe("weighted", () => {
	test.each([
		[100, 50],
		[349, 174.5],
		[350, 350],
		[1799, 1799],
		[1800, 2250],
		[6999, 8748.75],
		[7000, 10500],
		[23999, 35998.5],
		[24000, 54000],
	])("%p tokens weighs %p", (size, weight) => {
		expect(weighted([size])).toEqual([weight]);
	});

	test("keeps the order of the sizes", () => {
		expect(weighted([120, 90, 2400, 400, 8000])).toEqual([60, 45, 3000, 400, 12000]);
	});

	test("leaves fractional results unrounded", () => {
		expect(weighted([1, 1801])).toEqual([0.5, 2251.25]);
	});

	test("an empty list gives an empty list", () => {
		expect(weighted([])).toEqual([]);
	});

	test("rejects a negative size with the same RangeError as bucketOf", () => {
		let expected: unknown;
		try {
			bucketOf(-1);
		} catch (error) {
			expected = error;
		}
		expect(expected).toBeInstanceOf(RangeError);
		expect(() => weighted([120, -1])).toThrow(RangeError);
		expect(() => weighted([120, -1])).toThrow((expected as RangeError).message);
	});
});

