+/**
+ * The sum of the `weighted` sizes of the Turns in each Bucket, keyed like the
+ * `histogram` rows: largest Bucket first, 0 for an empty Bucket, `huge` left
+ * out when no size falls in it. Each size is rounded before summing.
+ *
+ * @throws RangeError when a size is negative, `NaN` or infinite (see `bucketOf`).
+ */
+export function bucketTotals(sizes: number[]): Map<Bucket, number> {
+	const totals = new Map<Bucket, number>(histogram(sizes).map(({ bucket }) => [bucket, 0]));
+	const weights = weighted(sizes);
+	for (const [index, size] of sizes.entries()) {
+		const bucket = bucketOf(size);
+		totals.set(bucket, (totals.get(bucket) ?? 0) + (weights[index] ?? 0));
+	}
+	return totals;
+}

