1:/**
2: * An equal share of the room each, with what a small claim does not use
3: * released to the rest.
4: *
5: * Used wherever several pieces of one thing compete for room: the messages
6: * of a Turn being embedded, and the tool results inside a recollection being
7: * shortened. Equal-then-released rather than proportional, because
8: * proportional shares give the largest piece the most room, which is exactly
9: * the piece least worth carrying whole.
10: *
11: * Returns what each claim may spend, parallel to `sizes`. A claim that gets
12: * nothing gets zero. Room is in characters at both call sites, but nothing
13: * here depends on the unit.
14: */
15:export function shares(sizes: number[], room: number): number[] {
16:	const allocation = new Array<number>(sizes.length).fill(0);
17:	let remaining = Math.max(room, 0);
18:	const open = sizes.map((_, index) => index);
19:
20:	while (open.length > 0) {
21:		const share = Math.floor(remaining / open.length);
22:		if (share <= 0) break;
23:		// Everything at or under an equal share is settled at its own size,
24:		// and what it did not take is shared out again. When nothing is under
25:		// the share, every claim is larger than the room can meet and they
26:		// divide what is left evenly.
27:		const settled = open.filter((index) => (sizes[index] ?? 0) <= share);
28:		if (settled.length === 0) {
29:			for (const index of open) allocation[index] = share;
30:			break;
31:		}
32:		for (const index of settled) {
33:			const size = sizes[index] ?? 0;
34:			allocation[index] = size;
35:			remaining -= size;
36:		}
37:		for (const index of settled) open.splice(open.indexOf(index), 1);
38:	}
39:
40:	return allocation;
41:}
assistant: Each claim gets the same amount, `Math.floor(room / sizes.length)`, because no claim fits within that equal share. Any remainder from the rounding down goes unused, and if the room is smaller than the number of claims (or zero or negative), every claim gets 0.

