// owner: OWN-9314
import { bucketTotals, formatCount, histogram, labelOf } from "./budget-table.ts";

/**
 * The budget table of `sizes` as rows (notes/legend.md): the header, then one
 * `<label> | <count> | <weighted total>` row per `histogram` entry, in its
 * order, with the weighted total shown through `formatCount`.
 *
 * @throws RangeError when a size is negative, `NaN` or infinite (see `bucketOf`).
 */
export function renderTable(sizes: number[]): string[] {
	const totals = bucketTotals(sizes);
	return [
		"bucket | turns | weighted",
		...histogram(sizes).map(
			({ bucket, count }) => `${labelOf(bucket)} | ${count} | ${formatCount(totals.get(bucket) ?? 0)}`,
		),
	];
}

