describe("bucketTotals", () => {
	test("sums the weighted sizes per bucket in histogram order", () => {
		expect([...bucketTotals([120, 90, 2400, 400, 8000])]).toEqual([
			["large", 12000],
			["medium", 3000],
			["small", 400],
			["tiny", 110],
		]);
	});

	test("rounds each Turn before summing", () => {
		// 90 weighs 45, rounded to 50 per Turn; rounding the 90 sum would give 90.
		expect(bucketTotals([90, 90]).get("tiny")).toBe(100);
	});

	test("with a huge size, puts huge first", () => {
		expect([...bucketTotals([24000, 30000, 100])]).toEqual([
			["huge", 121500],
			["large", 0],
			["medium", 0],
			["small", 0],
			["tiny", 50],
		]);
	});

	test("rejects a negative size with a RangeError", () => {
		expect(() => bucketTotals([120, -1])).toThrow(RangeError);
	});
});

describe("formatCount", () => {
	test.each([
		[0, "0"],
		[740, "740"],
		[999, "999"],
		[1000, "1.0k"],
		[1234, "1.2k"],
		[1250, "1.3k"],
		[1150, "1.2k"],
		[1949, "1.9k"],
		[9950, "10.0k"],
		[12000, "12.0k"],
	] as const)("%p shows as %p", (n, shown) => {
		expect(formatCount(n)).toBe(shown);
	});
});

describe("labelOf", () => {
	test.each([
		["tiny", "crumbs"],
		["small", "bites"],
		["medium", "meals"],
		["large", "feasts"],
		["huge", "banquets"],
	] as const)("%p rows are labelled %p", (bucket, label) => {
		expect(labelOf(bucket)).toBe(label);
	});
});

