9:export type Bucket = (typeof BUCKETS)[number];
10:
11:/** Exclusive upper bound of each Bucket; `huge` has none. */
12:const BELOW: Record<Bucket, number> = {
13:	tiny: 350,
14:	small: 1800,
15:	medium: 7000,
16:	large: 24000,
17:	huge: Number.POSITIVE_INFINITY,
18:};
19:
20:/** What a Turn's size is multiplied by, per Bucket (notes/weights.md). */
21:const WEIGHT: Record<Bucket, number> = {
22:	tiny: 0.5,
23:	small: 1,
24:	medium: 1.25,
25:	large: 1.5,
26:	huge: 2.25,
27:};
28:
29:/**
30: * The Bucket a Turn of `tokens` estimated tokens falls in; each bound is the
31: * next Bucket's start, so 350 is `small` and 24000 is `huge`.
32: *
33: * @throws RangeError when `tokens` is negative, `NaN` or infinite.
34: */
35:export function bucketOf(tokens: number): Bucket {
36:	if (!Number.isFinite(tokens) || tokens < 0) {
37:		throw new RangeError(`Turn size must be a finite, non-negative token count, got ${tokens}`);
38:	}
39:	for (const bucket of BUCKETS) if (tokens < BELOW[bucket]) return bucket;
40:	return "huge";
41:}
42:
43:/**
44: * Estimated tokens of each Turn in `messages`, in order: one
45: * `approximateTokens` estimate per Turn that `reconstructTurns` finds.
46: *
47: * Leading-Turn rule: messages before the first user prompt (e.g. a system
48: * message) come back from `reconstructTurns` as a leading Turn with no prompt.
49: * That Turn is dropped, so its tokens count toward no size. It is recognised
50: * by its first message not being a user message, not by an empty `prompt`: a
51: * real user prompt with empty text still starts a Turn and is kept.
52: */
