import { describe, expect, test } from "bun:test";

import { bucketOf, bucketTotals, formatCount, histogram, labelOf, totalOf, turnSizes } from "./budget-table.ts";
import { renderTable } from "./budget-render.ts";
import type { HarnessMessage } from "./messages.ts";
import { approximateTokens } from "./tokens.ts";

describe("bucketOf", () => {
	test.each([
		[0, "tiny"],
		[349, "tiny"],
		[350, "small"],
		[1799, "small"],
		[1800, "medium"],
		[6999, "medium"],
		[7000, "large"],
		[23999, "large"],
		[24000, "huge"],
	] as const)("%p tokens is %p", (tokens, bucket) => {
		expect(bucketOf(tokens)).toBe(bucket);
	});

	test("a fraction below a bound stays in the lower bucket", () => {
		expect(bucketOf(349.5)).toBe("tiny");
		expect(bucketOf(23999.9)).toBe("large");
	});

	test.each([-1, -0.5, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY])(
		"rejects %p with a RangeError",
		(tokens) => {
			expect(() => bucketOf(tokens)).toThrow(RangeError);
		},
	);
});

describe("turnSizes", () => {
	const lead: HarnessMessage = { role: "assistant", content: "Picking up where we left off." };
	const firstPrompt: HarnessMessage = { role: "user", content: "List the files in src." };
	const firstReply: HarnessMessage = { role: "assistant", content: "budget-table.ts, messages.ts, shares.ts" };
	const secondPrompt: HarnessMessage = { role: "user", content: "Now explain shares()." };
	const secondReply: HarnessMessage = {
		role: "assistant",
		content: [{ type: "text", text: "It splits the room equally, releasing what small claims leave." }],
	};
	const messages = [lead, firstPrompt, firstReply, secondPrompt, secondReply];

	test("sizes each prompted Turn over its own messages and drops the leading Turn", () => {
		expect(turnSizes(messages)).toEqual([
			approximateTokens([firstPrompt, firstReply]),
			approximateTokens([secondPrompt, secondReply]),
		]);
	});

	test("the leading message counts toward no Turn", () => {
		const longLead: HarnessMessage = { ...lead, content: "x".repeat(4000) };
		expect(turnSizes([longLead, ...messages.slice(1)])).toEqual(turnSizes(messages));
	});

	test("keeps the first Turn when the messages start with a prompt", () => {
		expect(turnSizes(messages.slice(1))).toEqual(turnSizes(messages));
	});
});

describe("histogram", () => {
	test("counts the sample sizes per bucket, largest bucket first", () => {
		expect(histogram([120, 90, 2400, 400, 8000])).toEqual([
			{ bucket: "large", count: 1 },
			{ bucket: "medium", count: 1 },
