		expect(renderTable([120, 90, 2400, 400, 8000])).toEqual([
			"bucket | turns | weighted",
			"feasts | 1 | 12.0k",
			"meals | 1 | 3.0k",
			"bites | 1 | 400",
			"crumbs | 2 | 110",
		]);
	});

	test("with a huge size, puts banquets first and shows empty buckets at 0", () => {
		expect(renderTable([24000, 30000, 100])).toEqual([
			"bucket | turns | weighted",
			"banquets | 2 | 121.5k",
			"feasts | 0 | 0",
			"meals | 0 | 0",
			"bites | 0 | 0",
			"crumbs | 1 | 50",
		]);
	});

	test("an empty list gives the header and every row but banquets at 0", () => {
		expect(renderTable([])).toEqual([
			"bucket | turns | weighted",
			"feasts | 0 | 0",
			"meals | 0 | 0",
			"bites | 0 | 0",
			"crumbs | 0 | 0",
		]);
	});

	test("switches a weighted total to thousands at 1000", () => {
		expect(renderTable([990])[3]).toBe("bites | 1 | 990");
		expect(renderTable([1000])[3]).toBe("bites | 1 | 1.0k");
	});

	test("rejects a negative size with a RangeError", () => {
		expect(() => renderTable([120, -1])).toThrow(RangeError);
	});
});

describe("summaryLine", () => {
	test("lays out the format.md example", () => {
		expect(summaryLine([1400, 7000, 1000], 20000)).toBe(
			"turns=3 · total=9400 · used=47% · peak=large · over=0",
		);
	});

	test("counts only Turns strictly over 9000 as over, and peaks at huge", () => {
		expect(summaryLine([9000, 9001, 24000], 10000)).toBe(
			"turns=3 · total=42001 · used=420% · peak=huge · over=2",
		);
	});

	test("rounds used down", () => {
		expect(summaryLine([1999], 1000)).toBe("turns=1 · total=1999 · used=199% · peak=medium · over=0");
	});

	test("no Turns peak at none", () => {
		expect(summaryLine([], 1000)).toBe("turns=0 · total=0 · used=0% · peak=none · over=0");
	});

	test("rejects a negative size or a non-positive budget with a RangeError", () => {
		expect(() => summaryLine([120, -1], 1000)).toThrow(RangeError);
		expect(() => summaryLine([120], 0)).toThrow(RangeError);
	});
});

