import { describe, expect, test } from "bun:test";

import {
	bucketOf,
	bucketTotals,
	formatCount,
	histogram,
	labelOf,
	summaryLine,
	totalOf,
	turnSizes,
} from "./budget-table.ts";
import { renderTable } from "./budget-render.ts";
import type { HarnessMessage } from "./messages.ts";
import { approximateTokens } from "./tokens.ts";

describe("bucketOf", () => {
	test.each([
		[0, "tiny"],
		[349, "tiny"],
		[350, "small"],
		[1799, "small"],
		[1800, "medium"],
		[6999, "medium"],
		[7000, "large"],
		[23999, "large"],
		[24000, "huge"],
	] as const)("%p tokens is %p", (tokens, bucket) => {
		expect(bucketOf(tokens)).toBe(bucket);
	});

	test("a fraction below a bound stays in the lower bucket", () => {
		expect(bucketOf(349.5)).toBe("tiny");
		expect(bucketOf(23999.9)).toBe("large");
	});

	test.each([-1, -0.5, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY])(
		"rejects %p with a RangeError",
		(tokens) => {
			expect(() => bucketOf(tokens)).toThrow(RangeError);
		},
	);
});

describe("turnSizes", () => {
	const lead: HarnessMessage = { role: "assistant", content: "Picking up where we left off." };
	const firstPrompt: HarnessMessage = { role: "user", content: "List the files in src." };
	const firstReply: HarnessMessage = { role: "assistant", content: "budget-table.ts, messages.ts, shares.ts" };
	const secondPrompt: HarnessMessage = { role: "user", content: "Now explain shares()." };
	const secondReply: HarnessMessage = {
		role: "assistant",
		content: [{ type: "text", text: "It splits the room equally, releasing what small claims leave." }],
	};
	const messages = [lead, firstPrompt, firstReply, secondPrompt, secondReply];

	test("sizes each prompted Turn over its own messages and drops the leading Turn", () => {
		expect(turnSizes(messages)).toEqual([
			approximateTokens([firstPrompt, firstReply]),
			approximateTokens([secondPrompt, secondReply]),
		]);
	});

	test("the leading message counts toward no Turn", () => {
		const longLead: HarnessMessage = { ...lead, content: "x".repeat(4000) };
		expect(turnSizes([longLead, ...messages.slice(1)])).toEqual(turnSizes(messages));
	});

	test("keeps the first Turn when the messages start with a prompt", () => {
		expect(turnSizes(messages.slice(1))).toEqual(turnSizes(messages));
	});
});

describe("histogram", () => {
	test("counts the sample sizes per bucket, largest bucket first", () => {
		expect(histogram([120, 90, 2400, 400, 8000])).toEqual([
			{ bucket: "large", count: 1 },
			{ bucket: "medium", count: 1 },
			{ bucket: "small", count: 1 },
			{ bucket: "tiny", count: 2 },
		]);
	});

	test("with no huge size, leaves huge out but keeps other empty buckets at 0", () => {
		expect(histogram([10, 7000, 23999])).toEqual([
			{ bucket: "large", count: 2 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 0 },
			{ bucket: "tiny", count: 1 },
		]);
	});

	test("with a huge size, puts huge first", () => {
		expect(histogram([24000, 5])).toEqual([
			{ bucket: "huge", count: 1 },
			{ bucket: "large", count: 0 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 0 },
			{ bucket: "tiny", count: 1 },
		]);
	});

	test("an empty list gives every bucket but huge at 0", () => {
		expect(histogram([])).toEqual([
			{ bucket: "large", count: 0 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 0 },
			{ bucket: "tiny", count: 0 },
		]);
	});
});

describe("totalOf", () => {
	test("sums the sizes, and an empty list sums to 0", () => {
		expect(totalOf([120, 90, 2400, 400, 8000])).toBe(11010);
		expect(totalOf([])).toBe(0);
	});
});

describe("bucketTotals", () => {
	test("sums the weighted sizes per bucket in histogram order", () => {
		expect([...bucketTotals([120, 90, 2400, 400, 8000])]).toEqual([
			["large", 12000],
			["medium", 3000],
			["small", 400],
			["tiny", 110],
		]);
	});

	test("rounds each Turn before summing", () => {
		// 90 weighs 45, rounded to 50 per Turn; rounding the 90 sum would give 90.
		expect(bucketTotals([90, 90]).get("tiny")).toBe(100);
	});

	test("with a huge size, puts huge first", () => {
		expect([...bucketTotals([24000, 30000, 100])]).toEqual([
			["huge", 121500],
			["large", 0],
			["medium", 0],
			["small", 0],
			["tiny", 50],
		]);
	});

	test("rejects a negative size with a RangeError", () => {
		expect(() => bucketTotals([120, -1])).toThrow(RangeError);
	});
});

describe("formatCount", () => {
	test.each([
		[0, "0"],
		[740, "740"],
		[999, "999"],
		[1000, "1.0k"],
		[1234, "1.2k"],
		[1250, "1.3k"],
		[1150, "1.2k"],
		[1949, "1.9k"],
		[9950, "10.0k"],
		[12000, "12.0k"],
	] as const)("%p shows as %p", (n, shown) => {
		expect(formatCount(n)).toBe(shown);
	});
});

describe("labelOf", () => {
	test.each([
		["tiny", "crumbs"],
		["small", "bites"],
		["medium", "meals"],
		["large", "feasts"],
		["huge", "banquets"],
	] as const)("%p rows are labelled %p", (bucket, label) => {
		expect(labelOf(bucket)).toBe(label);
	});
});

describe("renderTable", () => {
	test("renders the header, then one row per histogram entry for the sample", () => {
		expect(renderTable([120, 90, 2400, 400, 8000])).toEqual([
			"bucket | turns | weighted",
			"feasts | 1 | 12.0k",
			"meals | 1 | 3.0k",
			"bites | 1 | 400",
			"crumbs | 2 | 110",
		]);
	});

	test("with a huge size, puts banquets first and shows empty buckets at 0", () => {
		expect(renderTable([24000, 30000, 100])).toEqual([
			"bucket | turns | weighted",
			"banquets | 2 | 121.5k",
			"feasts | 0 | 0",
			"meals | 0 | 0",
			"bites | 0 | 0",
			"crumbs | 1 | 50",
		]);
	});

	test("an empty list gives the header and every row but banquets at 0", () => {
		expect(renderTable([])).toEqual([
			"bucket | turns | weighted",
			"feasts | 0 | 0",
			"meals | 0 | 0",
			"bites | 0 | 0",
			"crumbs | 0 | 0",
		]);
	});

	test("switches a weighted total to thousands at 1000", () => {
		expect(renderTable([990])[3]).toBe("bites | 1 | 990");
		expect(renderTable([1000])[3]).toBe("bites | 1 | 1.0k");
	});

	test("rejects a negative size with a RangeError", () => {
		expect(() => renderTable([120, -1])).toThrow(RangeError);
	});
});

describe("summaryLine", () => {
	test("lays out the format.md example", () => {
		expect(summaryLine([1400, 7000, 1000], 20000)).toBe(
			"turns=3 · total=9400 · used=47% · peak=large · over=0",
		);
	});

	test("counts only Turns strictly over 9000 as over, and peaks at huge", () => {
		expect(summaryLine([9000, 9001, 24000], 10000)).toBe(
			"turns=3 · total=42001 · used=420% · peak=huge · over=2",
		);
	});

	test("rounds used down", () => {
		expect(summaryLine([1999], 1000)).toBe("turns=1 · total=1999 · used=199% · peak=medium · over=0");
	});

	test("no Turns peak at none", () => {
		expect(summaryLine([], 1000)).toBe("turns=0 · total=0 · used=0% · peak=none · over=0");
	});

	test("rejects a negative size with a RangeError", () => {
		expect(() => summaryLine([120, -1], 1000)).toThrow(RangeError);
	});

	test("rejects a budget that is not a positive finite number with a RangeError", () => {
		for (const budget of [0, -1, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY]) {
			expect(() => summaryLine([120], budget)).toThrow(RangeError);
		}
		expect(summaryLine([120], 0.5)).toBe("turns=1 · total=120 · used=24000% · peak=tiny · over=0");
	});
});

