/** Turns larger than this many tokens (strictly) count toward `over=`. */
const OVER_TOKENS = 9000;

/**
 * The one-line summary of `sizes` against `budget` (notes/format.md): fields
 * joined by ` · `, in order `turns=<n>`, `total=<n>` (unweighted sum),
 * `used=<p>%` (total as a percentage of `budget`, rounded down, may exceed
 * 100), then the footer (notes/buckets.md): `peak=<bucket>`, the largest
 * Bucket holding a Turn (`none` for no Turns), and `over=<n>`, the Turns
 * larger than 9000 tokens.
 *
 * @throws RangeError when a size is negative, `NaN` or infinite (see `bucketOf`),
 *   or when `budget` is not a finite positive number.
 */
export function summaryLine(sizes: number[], budget: number): string {
	if (!Number.isFinite(budget) || budget <= 0) {
		throw new RangeError(`Budget must be a finite, positive token count, got ${budget}`);
	}
	const total = totalOf(sizes);
	const peak = histogram(sizes).find(({ count }) => count > 0)?.bucket ?? "none";
	return [
		`turns=${sizes.length}`,
		`total=${total}`,
		`used=${Math.floor((total * 100) / budget)}%`,
		`peak=${peak}`,
		`over=${sizes.filter((size) => size > OVER_TOKENS).length}`,
	].join(" · ");
}
